30	import type { PageType } from "@/types";
31	import { cn } from "@/lib/utils";
32	
33	/** Basic URL validation — checks structure, not reachability */
34	function isValidUrl(str: string): boolean {
35	  try {
36	    const url = new URL(str.startsWith("http") ? str : `https://${str}`);
37	    return url.protocol === "https:" || url.protocol === "http:";
38	  } catch {
39	    return false;
40	  }
41	}
42	
43	/** Normalize URL: prepend https:// if missing */
44	function normalizeUrl(str: string): string {
45	  const trimmed = str.trim();
46	  if (!trimmed) return trimmed;
47	  if (/^https?:\/\//i.test(trimmed)) return trimmed;
48	  return `https://${trimmed}`;
49	}
50	
51	// ── Map scan status to step index ───────────────────────────────
52	
53	function statusToStep(status: string): number {
54	  switch (status) {
55	    case "pending": return 0;
56	    case "analyzing": return 3;
57	    case "completed": return SCAN_STEPS.length;
58	    case "failed": return -1;
59	    default: return 0;
60	  }
61	}
62	
63	const Scan = () => {
64	  const navigate = useNavigate();
65	  const [searchParams] = useSearchParams();
66	  const [rawUrl, setRawUrl] = useState(searchParams.get("url") || "");
67	  const [pageType, setPageType] = useState<PageType>(
68	    (searchParams.get("type") as PageType) || "landing"
69	  );
70	  const [urlError, setUrlError] = useState<string | null>(null);
71	
72	  // activeScanId drives the polling query
73	  const [activeScanId, setActiveScanId] = useState<string | null>(null);
74	  const [simulatedStep, setSimulatedStep] = useState(-1);
75	
76	  const inputId = useId();
77	  const { user, profile } = useAuth();
78	  const isAuthenticated = !!user;
79	  const createScan = useCreateScan();
80	
81	  const scansUsed = profile?.scans_used ?? 0;
82	  const scanLimit = profile?.scan_limit ?? 3;
83	  const scansRemaining = scanLimit - scansUsed;
84	  const atLimit = scansRemaining <= 0;
85	
86	  // Poll the scan row while it's pending/analyzing
87	  const { data: pollingScan } = useScan(activeScanId ?? undefined, {
88	    refetchInterval: activeScanId ? 2000 : false,
89	  });
90	
91	  const isAnalyzing = activeScanId !== null;
92	  const normalizedUrl = normalizeUrl(rawUrl);
93	
94	  const totalSteps = SCAN_STEPS.length;
95	  const currentStep = isAnalyzing
96	    ? pollingScan
97	      ? statusToStep(pollingScan.status)
98	      : simulatedStep
99	    : -1;
100	  const progressPercent = currentStep < 0 ? 0 : Math.round(((currentStep + 1) / totalSteps) * 100);
101	
102	  // When polling finds a completed/failed scan, navigate or show error
103	  useEffect(() => {
104	    if (!pollingScan) return;
105	    if (pollingScan.status === "completed") {
106	      setTimeout(() => navigate(`/reports/${pollingScan.id}`), 600);
107	    } else if (pollingScan.status === "failed") {
108	      setActiveScanId(null);
109	      setSimulatedStep(-1);
110	      toast.error("Scan failed. Please try again.", {
111	        action: { label: "Retry", onClick: () => startAnalysis() },
112	      });
113	    }
114	    // eslint-disable-next-line react-hooks/exhaustive-deps
115	  }, [pollingScan?.status]);
116	
117	  // Simulate step progression while waiting for the edge function
118	  useEffect(() => {
119	    if (!isAnalyzing || !activeScanId) return;
120	    if (pollingScan?.status === "completed" || pollingScan?.status === "failed") return;
121	    if (simulatedStep >= totalSteps - 1) return;
122	
123	    const durations = [900, 1400, 1200, 1100, 1300, 1000, 1600];
124	    const timer = setTimeout(
125	      () => setSimulatedStep((prev) => prev + 1),
126	      durations[simulatedStep] ?? 1200
127	    );
128	    return () => clearTimeout(timer);
129	    // totalSteps is derived from a constant — safe to omit
130	    // eslint-disable-next-line react-hooks/exhaustive-deps
131	  }, [isAnalyzing, activeScanId, simulatedStep, pollingScan?.status]);
132	
133	  const startAnalysis = useCallback(() => {
134	    setUrlError(null);
135	    if (!rawUrl.trim()) {
136	      setUrlError("Please enter a URL.");
137	      return;
138	    }
139	    if (!isValidUrl(normalizedUrl)) {
140	      setUrlError("Enter a valid URL like https://example.com/page");
141	      return;
142	    }
143	
144	    // Unauthenticated users: gate the scan and redirect to signup
145	    if (!isAuthenticated) {
146	      toast.info("Create a free account to start scanning", {
147	        description: "Sign up in seconds — no credit card required.",
148	        action: {
149	          label: "Sign up free",
150	          onClick: () =>
151	            navigate(
152	              `/signup?redirect=/scan&url=${encodeURIComponent(normalizedUrl)}`
153	            ),
154	        },
155	      });
156	      navigate(`/signup?redirect=/scan&url=${encodeURIComponent(normalizedUrl)}`);
157	      return;
158	    }
159	
160	    if (atLimit) return;
161	
162	    setSimulatedStep(0);
163	
164	    createScan.mutate(
165	      { url: normalizedUrl, page_type: pageType },
166	      {
167	        onSuccess: (scan) => {
168	          setActiveScanId(scan.id);
169	        },
170	        onError: (err: unknown) => {
171	          setSimulatedStep(-1);
172	          const message = err instanceof Error ? err.message : "Failed to start scan";
173	          toast.error(message);
174	        },
175	      }
176	    );
177	  }, [rawUrl, normalizedUrl, pageType, isAuthenticated, atLimit, createScan, navigate]);
178	
179	  const handleSubmit = (e: React.FormEvent) => {
180	    e.preventDefault();
181	    startAnalysis();
182	  };
183	
184	  // ── Analysis Progress View ──────────────────────────────────
185	  if (isAnalyzing) {
186	    let hostname = rawUrl;
187	    try { hostname = new URL(normalizedUrl).hostname; } catch { /* keep raw */ }
188	
189	    const displayStep = Math.max(0, currentStep);
190	
191	    return (
192	      <PageTransition>
193	        <div className="mx-auto max-w-2xl space-y-6">
194	          <div>
195	            <h2 className="text-xl font-semibold tracking-tight text-foreground">Analyzing your page</h2>
196	            <p className="mt-1 text-sm text-muted-foreground">
197	              Scanning <span className="font-medium text-foreground">{hostname}</span> — this usually takes 20-40 seconds
198	            </p>
199	          </div>
200	
201	          {/* Progress bar */}
202	          <div className="space-y-1.5">
203	            <div className="flex items-center justify-between text-sm">
204	              <span className="text-muted-foreground">
205	                Step {Math.min(displayStep + 1, totalSteps)} of {totalSteps}
206	              </span>
207	              <span className="tabular-nums font-medium text-foreground">{Math.min(progressPercent, 100)}%</span>
208	            </div>
209	            <Progress value={Math.min(progressPercent, 100)} className="h-2" />
210	          </div>
211	
212	          {/* Browser frame */}
213	          <BrowserFrame url={normalizedUrl}>
214	            <div className="relative flex h-52 items-center justify-center bg-gradient-to-br from-slate-50 via-white to-slate-50">
215	              {/* Scanning animation */}
216	              <div className="absolute inset-x-0 top-0 h-1 overflow-hidden">
217	                <div className="h-full w-1/3 animate-[shimmer_1.5s_ease-in-out_infinite] bg-gradient-to-r from-transparent via-primary/30 to-transparent" />
218	              </div>
219	              <div className="text-center">
220	                <Loader2 className="mx-auto mb-3 h-8 w-8 animate-spin text-primary" />
221	                <p className="text-sm font-medium text-muted-foreground">
222	                  {displayStep < totalSteps ? SCAN_STEPS[displayStep]?.label : "Finalizing report"}...
223	                </p>
224	              </div>
225	            </div>
226	          </BrowserFrame>
227	
228	          {/* Timeline */}
229	          <Card className="border-border/50 shadow-soft">
230	            <CardContent className="p-6">
231	              <ScanProgressTimeline steps={SCAN_STEPS} currentStep={displayStep} />
232	            </CardContent>
233	          </Card>
234	        </div>
235	      </PageTransition>
236	    );
237	  }
238	
239	  // ── URL Input Form ──────────────────────────────────────────
240	  return (
241	    <PageTransition>
242	      <div className="mx-auto max-w-2xl space-y-8">
243	        <div className="text-center">
244	          <h2 className="text-xl font-semibold tracking-tight text-foreground">Analyze your page</h2>
245	          <p className="mt-2 text-muted-foreground">
246	            Enter any URL to get a detailed CRO audit with actionable recommendations
247	          </p>
248	        </div>
249	
250	        {/* URL Input Card */}
251	        <Card className="border-border/50 shadow-soft">
252	          <CardContent className="p-8">
253	            <form onSubmit={handleSubmit} className="space-y-4">
254	              <div>
255	                <label htmlFor={inputId} className="mb-1.5 block text-sm font-medium text-foreground">
256	                  Page URL
257	                </label>
258	                <div className="relative">
259	                  <Globe className="absolute left-4 top-1/2 h-4.5 w-4.5 -translate-y-1/2 text-muted-foreground" />
260	                  <Input
261	                    id={inputId}
262	                    type="text"
263	                    placeholder="example.com/landing-page"
264	                    value={rawUrl}
265	                    onChange={(e) => { setRawUrl(e.target.value); setUrlError(null); }}
266	                    className={cn(
267	                      "h-14 rounded-xl border-border/50 bg-white pl-11 pr-5 text-base placeholder:text-muted-foreground focus-visible:border-primary focus-visible:ring-primary/20",
268	                      urlError && "border-red-300 focus-visible:border-red-400 focus-visible:ring-red-400/20"
269	                    )}
270	                  />
271	                </div>
272	                {urlError && (
273	                  <p className="mt-1.5 flex items-center gap-1 text-sm text-red-600">
274	                    <AlertCircle className="h-3.5 w-3.5" />
275	                    {urlError}
276	                  </p>
277	                )}
278	              </div>
279	
280	              <div>
281	                <label className="mb-1.5 block text-sm font-medium text-foreground">Page type</label>
282	                <Select value={pageType} onValueChange={(v) => setPageType(v as PageType)}>
283	                  <SelectTrigger className="h-12 rounded-xl border-border/50 bg-white">
284	                    <SelectValue placeholder="Select page type" />
285	                  </SelectTrigger>
286	                  <SelectContent>
287	                    {PAGE_TYPES.map((type) => (
288	                      <SelectItem key={type.value} value={type.value}>
289	                        {type.label}
290	                      </SelectItem>
291	                    ))}
292	                  </SelectContent>
293	                </Select>
294	                <p className="mt-1 text-xs text-muted-foreground">
295	                  Page type affects how we weight each CRO pillar in the overall score
296	                </p>
297	              </div>
298	
299	              <Button
300	                type="submit"
301	                className="h-14 w-full rounded-xl text-base font-semibold"
302	                disabled={!rawUrl.trim() || (isAuthenticated && (atLimit || createScan.isPending))}
303	              >
304	                {isAuthenticated && atLimit ? (
305	                  "Scan limit reached — Upgrade to continue"
306	                ) : isAuthenticated && createScan.isPending ? (
307	                  <>
308	                    <Loader2 className="mr-2 h-5 w-5 animate-spin" />
309	                    Starting scan...
310	                  </>
311	                ) : !isAuthenticated ? (
312	                  <>
313	                    <Lock className="mr-2 h-5 w-5" />
314	                    Sign Up to Start Analysis
315	                  </>
316	                ) : (
317	                  <>
318	                    <ScanLine className="mr-2 h-5 w-5" />
319	                    Start Analysis
320	                  </>
321	                )}
322	              </Button>
323	            </form>
324	
325	            {/* Usage indicator — only shown to authenticated users */}
326	            {isAuthenticated ? (
327	              <div className="mt-4 flex items-center justify-center gap-4 text-xs text-muted-foreground">
328	                <span className="flex items-center gap-1">
329	                  {atLimit ? (
330	                    <AlertCircle className="h-3.5 w-3.5 text-red-500" />
331	                  ) : scansRemaining === 1 ? (
332	                    <AlertCircle className="h-3.5 w-3.5 text-amber-500" />
333	                  ) : (
334	                    <Info className="h-3.5 w-3.5" />
335	                  )}
336	                  {scansUsed}/{scanLimit} scans used this month
337	                </span>
338	                <span>&middot;</span>
339	                <span>~30 seconds per scan</span>
340	              </div>
341	            ) : (
342	              <div className="mt-4 rounded-lg border border-blue-100 bg-blue-50/60 px-4 py-3 text-center">
343	                <p className="text-xs text-blue-700">
344	                  Free account — 3 scans/month, no credit card required.{" "}
345	                  <a href="/signup" className="font-medium underline underline-offset-2 hover:text-blue-900">
346	                    Create account
347	                  </a>
348	                </p>
349	              </div>
350	            )}
351	          </CardContent>
352	        </Card>
353	
354	        {/* What we analyze */}
355	        <div>
356	          <h3 className="mb-4 text-center text-xs font-semibold uppercase tracking-widest text-muted-foreground">
357	            7 pillars we analyze
358	          </h3>
359	          <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">
360	            {CRO_PILLARS.map((pillar) => {
361	              const Icon = pillar.icon;
362	              return (
363	                <Card
364	                  key={pillar.key}
365	                  className="group border-border/50 shadow-soft hover:shadow-soft-md transition-all"
366	                >
367	                  <CardContent className="flex flex-col items-center p-4 text-center">
368	                    <div className="mb-2.5 flex h-9 w-9 items-center justify-center rounded-lg bg-primary/8 group-hover:bg-primary/15 transition-colors">
369	                      <Icon className="h-4 w-4 text-primary" />
370	                    </div>
371	                    <p className="text-xs font-medium text-foreground leading-tight">
372	                      {pillar.label}
373	                    </p>
374	                    <p className="mt-1 text-[10px] leading-snug text-muted-foreground">
375	                      {Math.round(pillar.weight * 100)}% weight
376	                    </p>
377	                  </CardContent>
378	                </Card>
379	              );
380	            })}
381	          </div>
382	        </div>
383	
384	        {/* How scoring works */}
385	        <Card className="border-border/40 bg-muted/30 shadow-none">
386	          <CardContent className="p-5">
387	            <div className="flex items-start gap-3">
388	              <Info className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground" />
389	              <div className="text-xs text-muted-foreground leading-relaxed">
390	                <span className="font-medium text-foreground">How scoring works:</span> Each pillar is scored 0-100 based on specific checks.
391	                Pillar weights vary by page type — for example, CTA Effectiveness is weighted 22% on landing pages but only 12% on blog posts.
392	                Your overall score is a weighted average compared against industry benchmarks.
393	              </div>
394	            </div>
395	          </CardContent>
396	        </Card>
397	      </div>
398	    </PageTransition>
399	  );
400	};
401	
