1	import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
2	import supabase from "@/lib/supabase";
3	import { useAuth } from "@/contexts/AuthContext";
4	import type { Scan, PageType } from "@/types";
5	import type { ScanRow } from "@/types/database";
6	
7	// ── Query keys ──────────────────────────────────────────────────
8	
9	export const scanKeys = {
10	  all: ["scans"] as const,
11	  lists: () => [...scanKeys.all, "list"] as const,
12	  list: (userId: string) => [...scanKeys.lists(), userId] as const,
13	  details: () => [...scanKeys.all, "detail"] as const,
14	  detail: (id: string) => [...scanKeys.details(), id] as const,
15	};
16	
17	// ── Row → App type mapper ───────────────────────────────────────
18	
19	function rowToScan(row: ScanRow): Scan {
20	  return {
21	    id: row.id,
22	    user_id: row.user_id,
23	    url: row.url,
24	    favicon_url: row.favicon_url,
25	    page_title: row.page_title,
26	    page_type: row.page_type,
27	    status: row.status,
28	    overall_score: row.overall_score,
29	    issues_found: row.issues_found,
30	    critical_issues: row.critical_issues,
31	    warnings: row.warnings,
32	    quick_wins: row.quick_wins,
33	    screenshot_url: row.screenshot_url,
34	    device: row.device,
35	    created_at: row.created_at,
36	    completed_at: row.completed_at,
37	  };
38	}
39	
40	// ── useScans ────────────────────────────────────────────────────
41	
42	export function useScans() {
43	  const { user } = useAuth();
44	
45	  return useQuery({
46	    queryKey: scanKeys.list(user?.id ?? ""),
47	    queryFn: async (): Promise<Scan[]> => {
48	      if (!user?.id) return [];
49	
50	      const { data, error } = await supabase
51	        .from("scans")
52	        .select("*")
53	        .eq("user_id", user.id)
54	        .order("created_at", { ascending: false });
55	
56	      if (error) throw new Error(error.message);
57	      return (data as ScanRow[]).map(rowToScan);
58	    },
59	    enabled: !!user?.id,
60	    staleTime: 1000 * 30, // 30 seconds
61	  });
62	}
63	
64	// ── useScan ─────────────────────────────────────────────────────
65	
66	export function useScan(id: string | undefined, options?: { refetchInterval?: number | false }) {
67	  const { user } = useAuth();
68	
69	  return useQuery({
70	    queryKey: scanKeys.detail(id ?? ""),
71	    queryFn: async (): Promise<Scan | null> => {
72	      if (!id || !user?.id) return null;
73	
74	      const { data, error } = await supabase
75	        .from("scans")
76	        .select("*")
77	        .eq("id", id)
78	        .eq("user_id", user.id)
79	        .single();
80	
81	      if (error) {
82	        if (error.code === "PGRST116") return null;
83	        throw new Error(error.message);
84	      }
85	
86	      return rowToScan(data as ScanRow);
87	    },
88	    enabled: !!id && !!user?.id,
89	    refetchInterval: options?.refetchInterval,
90	    staleTime: 0,
91	  });
92	}
93	
94	// ── useCreateScan ───────────────────────────────────────────────
95	
96	interface CreateScanInput {
97	  url: string;
98	  page_type: PageType;
99	}
100	
101	export function useCreateScan() {
102	  const { user, refreshProfile } = useAuth();
103	  const queryClient = useQueryClient();
104	
105	  return useMutation({
106	    mutationFn: async ({ url, page_type }: CreateScanInput): Promise<Scan> => {
107	      if (!user?.id) throw new Error("Not authenticated");
108	
109	      // Insert the scan row first
110	      const { data: scanData, error: insertError } = await supabase
111	        .from("scans")
112	        .insert({
113	          user_id: user.id,
114	          url,
115	          page_type,
116	          status: "pending" as const,
117	        })
118	        .select("*")
119	        .single();
120	
121	      if (insertError) throw new Error(insertError.message);
122	
123	      const scan = rowToScan(scanData as ScanRow);
124	
125	      // Invoke edge function — fire and don't block the return
126	      // The edge function updates the scan row when done
127	      supabase.functions
128	        .invoke("analyze-url", {
129	          body: { scan_id: scan.id, url, page_type },
130	        })
131	        .catch((err: unknown) => {
132	          console.error("Edge function invocation failed:", err);
133	        });
134	
135	      return scan;
136	    },
137	    onSuccess: (data) => {
138	      if (!user?.id) return;
139	      // Optimistically prepend the new scan to the list cache
140	      queryClient.setQueryData<Scan[]>(scanKeys.list(user.id), (prev) =>
141	        prev ? [data, ...prev] : [data]
142	      );
143	      // Prime the detail cache
144	      queryClient.setQueryData(scanKeys.detail(data.id), data);
145	      // Refresh profile to show updated scans_used count
146	      refreshProfile();
147	    },
148	  });
149	}
150	
151	// ── useDeleteScan ───────────────────────────────────────────────
152	
153	export function useDeleteScan() {
154	  const { user } = useAuth();
155	  const queryClient = useQueryClient();
156	
157	  return useMutation({
158	    mutationFn: async (scanId: string): Promise<void> => {
159	      if (!user?.id) throw new Error("Not authenticated");
160	
161	      const { error } = await supabase
162	        .from("scans")
163	        .delete()
164	        .eq("id", scanId)
165	        .eq("user_id", user.id);
166	
167	      if (error) throw new Error(error.message);
168	    },
169	    onSuccess: (_data, scanId) => {
170	      if (!user?.id) return;
171	      // Remove from list cache
172	      queryClient.setQueryData<Scan[]>(scanKeys.list(user.id), (prev) =>
173	        prev ? prev.filter((s) => s.id !== scanId) : []
174	      );
175	      // Remove detail cache
176	      queryClient.removeQueries({ queryKey: scanKeys.detail(scanId) });
177	    },
178	  });
179	}
180	
181	// ── useRefreshScan ──────────────────────────────────────────────
182	// Creates a new scan for the same URL/page_type as an existing scan
183	
184	export function useRefreshScan() {
185	  const createScan = useCreateScan();
186	
187	  return useMutation({
188	    mutationFn: async (sourceScan: Pick<Scan, "url" | "page_type">): Promise<Scan> => {
189	      return createScan.mutateAsync({ url: sourceScan.url, page_type: sourceScan.page_type });
190	    },
191	  });
192	}
