425	function parseHtml(
426	  html: string,
427	  baseUrl: string,
428	): { domData: DomData; pageTitle: string; faviconUrl: string } {
429	  // Extract title
430	  const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
431	  const pageTitle = titleMatch ? decodeHtmlEntities(titleMatch[1].trim()) : "";
432	
433	  // Extract favicon
434	  const faviconMatch = html.match(
435	    /<link[^>]+rel=["'](?:shortcut )?icon["'][^>]+href=["']([^"']+)["']/i,
436	  ) ?? html.match(/<link[^>]+href=["']([^"']+)["'][^>]+rel=["'](?:shortcut )?icon["']/i);
437	  let faviconUrl = "";
438	  if (faviconMatch) {
439	    try {
440	      faviconUrl = new URL(faviconMatch[1], baseUrl).toString();
441	    } catch (_) {
442	      faviconUrl = faviconMatch[1];
443	    }
444	  }
445	
446	  // Extract meta description
447	  const metaMatch = html.match(
448	    /<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["']/i,
449	  ) ?? html.match(
450	    /<meta[^>]+content=["']([^"']+)["'][^>]+name=["']description["']/i,
451	  );
452	  const metaDescription = metaMatch ? decodeHtmlEntities(metaMatch[1]) : "";
453	
454	  // Extract headings h1-h4
455	  const headings: string[] = [];
456	  const headingRegex = /<h([1-4])[^>]*>([\s\S]*?)<\/h\1>/gi;
457	  let hMatch;
458	  while ((hMatch = headingRegex.exec(html)) !== null && headings.length < 20) {
459	    const text = stripTags(hMatch[2]).trim();
460	    if (text) headings.push(text);
461	  }
462	
463	  // Extract buttons and links with CTA-like text
464	  const ctaButtons: string[] = [];
465	  const ctaKeywords = /\b(get|start|try|sign|join|buy|shop|order|book|schedule|download|learn|see|watch|explore|discover|request|contact|subscribe)\b/i;
466	  const buttonRegex = /<(?:button|a)[^>]*>([\s\S]*?)<\/(?:button|a)>/gi;
467	  let btnMatch;
468	  while ((btnMatch = buttonRegex.exec(html)) !== null && ctaButtons.length < 15) {
469	    const text = stripTags(btnMatch[1]).trim();
470	    if (text && text.length < 60 && ctaKeywords.test(text)) {
471	      ctaButtons.push(text);
472	    }
473	  }
474	
475	  // Extract images
476	  const images: Array<{ src: string; alt: string }> = [];
477	  const imgRegex = /<img[^>]+>/gi;
478	  let imgMatch;
479	  while ((imgMatch = imgRegex.exec(html)) !== null && images.length < 20) {
480	    const srcMatch = imgMatch[0].match(/src=["']([^"']+)["']/i);
481	    const altMatch = imgMatch[0].match(/alt=["']([^"']*)["']/i);
482	    if (srcMatch) {
483	      images.push({
484	        src: srcMatch[1],
485	        alt: altMatch ? altMatch[1] : "",
486	      });
487	    }
488	  }
489	
490	  // Extract links
491	  const links: Array<{ text: string; href: string }> = [];
492	  const linkRegex = /<a[^>]+href=["']([^"'#][^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi;
493	  let linkMatch;
494	  while ((linkMatch = linkRegex.exec(html)) !== null && links.length < 30) {
495	    const text = stripTags(linkMatch[2]).trim();
496	    if (text && text.length < 80) {
497	      links.push({ text, href: linkMatch[1] });
498	    }
499	  }
500	
501	  // Count forms
502	  const forms = (html.match(/<form[^>]*>/gi) ?? []).length;
503	
504	  // Heuristic: extract testimonial-like text blocks (blockquote or q tags)
505	  const testimonials: string[] = [];
506	  const quoteRegex = /<(?:blockquote|q)[^>]*>([\s\S]*?)<\/(?:blockquote|q)>/gi;
507	  let qMatch;
508	  while ((qMatch = quoteRegex.exec(html)) !== null && testimonials.length < 5) {
509	    const text = stripTags(qMatch[1]).trim();
510	    if (text && text.length > 30) testimonials.push(text.slice(0, 300));
511	  }
512	
513	  // Extract body text (strip scripts, styles, nav, footer first)
514	  let bodyText = html
515	    .replace(/<script[\s\S]*?<\/script>/gi, "")
516	    .replace(/<style[\s\S]*?<\/style>/gi, "")
517	    .replace(/<nav[\s\S]*?<\/nav>/gi, "")
518	    .replace(/<footer[\s\S]*?<\/footer>/gi, "")
519	    .replace(/<header[\s\S]*?<\/header>/gi, "");
520	  bodyText = stripTags(bodyText).replace(/\s+/g, " ").trim();
521	
522	  // Detect trust badges from common keywords
523	  const trustBadges: string[] = [];
524	  const badgeKeywords = [
525	    "SSL", "GDPR", "SOC 2", "ISO", "PCI", "HIPAA", "BBB",
526	    "Trustpilot", "G2", "Capterra", "Product Hunt", "4.8", "4.9", "5.0",
527	    "money-back guarantee", "100% satisfaction", "secure checkout",
528	    "verified", "certified", "award",
529	  ];
530	  for (const kw of badgeKeywords) {
531	    if (html.toLowerCase().includes(kw.toLowerCase())) {
532	      trustBadges.push(kw);
533	    }
534	  }
535	
536	  return {
537	    domData: {
538	      headings,
539	      cta_buttons: ctaButtons,
540	      images,
541	      meta_description: metaDescription,
542	      body_text: bodyText,
543	      links,
544	      forms,
545	      testimonials,
546	      trust_badges: trustBadges,
547	    },
548	    pageTitle,
549	    faviconUrl,
550	  };
551	}
