554	
555	async function uploadScreenshot(
556	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
557	  supabase: Record<string, any>,
558	  base64Data: string,
559	  scanId: string,
560	): Promise<string> {
561	  // Decode base64 to Uint8Array
562	  const binaryStr = atob(base64Data);
563	  const bytes = new Uint8Array(binaryStr.length);
564	  for (let i = 0; i < binaryStr.length; i++) {
565	    bytes[i] = binaryStr.charCodeAt(i);
566	  }
567	
568	  const path = `${scanId}/screenshot.jpg`;
569	  const { error } = await supabase.storage
570	    .from("screenshots")
571	    .upload(path, bytes, {
572	      contentType: "image/jpeg",
573	      upsert: true,
574	    });
575	
576	  if (error) throw new Error(`Storage upload failed: ${error.message}`);
577	
578	  const { data } = supabase.storage.from("screenshots").getPublicUrl(path);
579	  return data.publicUrl;
580	}
