2	 * stripe-checkout — Edge Function
3	 *
4	 * Creates a Stripe Checkout Session for plan upgrades.
5	 *
6	 * Expected request body:
7	 *   { plan: 'pro' | 'agency'; billing_cycle: 'monthly' | 'annual' }
8	 *
9	 * Returns:
10	 *   { url: string } — Stripe-hosted checkout page URL
11	 *
12	 * Required env vars:
13	 *   STRIPE_SECRET_KEY
14	 *   STRIPE_PRICE_PRO_MONTHLY
15	 *   STRIPE_PRICE_PRO_ANNUAL
16	 *   STRIPE_PRICE_AGENCY_MONTHLY
17	 *   STRIPE_PRICE_AGENCY_ANNUAL
18	 *   SITE_URL  (for success/cancel redirect URLs)
19	 *   SUPABASE_URL
20	 *   SUPABASE_SERVICE_ROLE_KEY
21	 */
22	
23	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
24	import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
25	import Stripe from "https://esm.sh/stripe@14?target=deno";
26	
27	const corsHeaders = {
28	  "Access-Control-Allow-Origin": "*",
29	  "Access-Control-Allow-Headers":
30	    "authorization, x-client-info, apikey, content-type",
31	};
32	
33	// Price ID lookup table — driven by env vars to avoid hardcoding
34	function getPriceId(plan: string, billingCycle: string): string | null {
35	  const map: Record<string, string> = {
36	    "pro:monthly": Deno.env.get("STRIPE_PRICE_PRO_MONTHLY") ?? "",
37	    "pro:annual": Deno.env.get("STRIPE_PRICE_PRO_ANNUAL") ?? "",
38	    "agency:monthly": Deno.env.get("STRIPE_PRICE_AGENCY_MONTHLY") ?? "",
39	    "agency:annual": Deno.env.get("STRIPE_PRICE_AGENCY_ANNUAL") ?? "",
40	  };
41	  return map[`${plan}:${billingCycle}`] || null;
42	}
43	
44	serve(async (req: Request) => {
45	  // Handle CORS preflight
46	  if (req.method === "OPTIONS") {
47	    return new Response("ok", { headers: corsHeaders });
48	  }
49	
50	  try {
51	    // ── 1. Auth — verify the JWT and extract user ──────────────────
52	    const authHeader = req.headers.get("Authorization");
53	    if (!authHeader) {
54	      return new Response(
55	        JSON.stringify({ error: "Missing Authorization header" }),
56	        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
57	      );
58	    }
59	
60	    // Use anon client with user's JWT to resolve identity
61	    const supabaseUser = createClient(
62	      Deno.env.get("SUPABASE_URL") ?? "",
63	      Deno.env.get("SUPABASE_ANON_KEY") ?? "",
64	      { global: { headers: { Authorization: authHeader } } }
65	    );
66	
67	    const {
68	      data: { user },
69	      error: userError,
70	    } = await supabaseUser.auth.getUser();
71	
72	    if (userError || !user) {
73	      return new Response(
74	        JSON.stringify({ error: "Unauthorized" }),
75	        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
76	      );
77	    }
78	
79	    // ── 2. Parse + validate body ───────────────────────────────────
80	    let body: { plan?: string; billing_cycle?: string };
81	    try {
82	      body = await req.json();
83	    } catch {
84	      return new Response(
85	        JSON.stringify({ error: "Invalid JSON body" }),
86	        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
87	      );
88	    }
89	
90	    const { plan, billing_cycle } = body;
91	
92	    if (!plan || !["pro", "agency"].includes(plan)) {
93	      return new Response(
94	        JSON.stringify({ error: "Invalid plan. Must be 'pro' or 'agency'." }),
95	        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
96	      );
97	    }
98	
99	    if (!billing_cycle || !["monthly", "annual"].includes(billing_cycle)) {
100	      return new Response(
101	        JSON.stringify({ error: "Invalid billing_cycle. Must be 'monthly' or 'annual'." }),
102	        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
103	      );
104	    }
105	
106	    const priceId = getPriceId(plan, billing_cycle);
107	    if (!priceId) {
108	      console.error(`Missing price ID for ${plan}:${billing_cycle}`);
109	      return new Response(
110	        JSON.stringify({ error: "Pricing configuration error. Contact support." }),
111	        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
112	      );
113	    }
114	
115	    // ── 3. Get user's profile — check for existing Stripe customer ──
116	    // Use service role key for full DB access
117	    const supabaseAdmin = createClient(
118	      Deno.env.get("SUPABASE_URL") ?? "",
119	      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
120	    );
121	
122	    const { data: profile, error: profileError } = await supabaseAdmin
123	      .from("profiles")
124	      .select("id, email, full_name, stripe_customer_id")
125	      .eq("id", user.id)
126	      .single();
127	
128	    if (profileError || !profile) {
129	      console.error("Profile fetch error:", profileError);
130	      return new Response(
131	        JSON.stringify({ error: "User profile not found." }),
132	        { status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" } }
133	      );
134	    }
135	
136	    // ── 4. Stripe — find or create customer ───────────────────────
137	    const stripe = new Stripe(Deno.env.get("STRIPE_SECRET_KEY") ?? "", {
138	      apiVersion: "2024-06-20",
139	      httpClient: Stripe.createFetchHttpClient(),
140	    });
141	
142	    let stripeCustomerId: string = profile.stripe_customer_id ?? "";
143	
144	    if (!stripeCustomerId) {
145	      const customer = await stripe.customers.create({
146	        email: profile.email ?? user.email,
147	        name: profile.full_name ?? undefined,
148	        metadata: { supabase_user_id: user.id },
149	      });
150	      stripeCustomerId = customer.id;
151	
152	      // Persist the new customer ID immediately
153	      const { error: updateError } = await supabaseAdmin
154	        .from("profiles")
155	        .update({ stripe_customer_id: stripeCustomerId })
156	        .eq("id", user.id);
157	
158	      if (updateError) {
159	        // Non-fatal — checkout can proceed, customer ID will be captured from webhook
160	        console.error("Failed to persist stripe_customer_id:", updateError);
161	      }
162	    }
163	
164	    // ── 5. Create Checkout Session ─────────────────────────────────
165	    const origin = Deno.env.get("SITE_URL") ?? "http://localhost:5173";
166	
167	    const session = await stripe.checkout.sessions.create({
168	      customer: stripeCustomerId,
169	      mode: "subscription",
170	      line_items: [{ price: priceId, quantity: 1 }],
171	      success_url: `${origin}/dashboard?checkout=success`,
172	      cancel_url: `${origin}/pricing?checkout=cancelled`,
173	      allow_promotion_codes: true,
174	      subscription_data: {
175	        metadata: {
176	          user_id: user.id,
177	          plan,
178	        },
179	      },
180	      metadata: {
181	        user_id: user.id,
182	        plan,
183	      },
184	    });
185	
186	    return new Response(
187	      JSON.stringify({ url: session.url }),
188	      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
189	    );
190	  } catch (error: unknown) {
191	    const message = error instanceof Error ? error.message : "Internal server error";
192	    console.error("stripe-checkout error:", error);
193	    return new Response(
194	      JSON.stringify({ error: message }),
195	      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
196	    );
197	  }
198	});
