318	  const appUrl = Deno.env.get("APP_URL") ?? "https://app.convertscan.com";
319	
320	  let payload: EmailRequest;
321	  try {
322	    payload = await req.json() as EmailRequest;
323	  } catch {
324	    return jsonResponse({ error: "Invalid JSON body" }, 400);
325	  }
326	
327	  if (!payload.type || !payload.to) {
328	    return jsonResponse({ error: "type and to are required" }, 400);
329	  }
330	
331	  let subject: string;
332	  let html: string;
333	
334	  try {
335	    switch (payload.type) {
336	      case "welcome": {
337	        const result = buildWelcomeEmail(payload.to, payload.data, appUrl);
338	        subject = result.subject;
339	        html = result.html;
340	        break;
341	      }
342	      case "scan_complete": {
343	        const result = buildScanCompleteEmail(payload.to, payload.data, appUrl);
344	        subject = result.subject;
345	        html = result.html;
346	        break;
347	      }
348	      case "weekly_digest": {
