3	 *
4	 * Creates a Stripe Billing Portal session so users can manage their
5	 * subscription, payment method, and download invoices.
6	 *
7	 * Returns:
8	 *   { url: string } — Stripe-hosted portal URL
9	 *
10	 * Required env vars:
11	 *   STRIPE_SECRET_KEY
12	 *   SITE_URL               (for return_url redirect)
13	 *   SUPABASE_URL
14	 *   SUPABASE_ANON_KEY
15	 *   SUPABASE_SERVICE_ROLE_KEY
16	 */
17	
18	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
19	import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
20	import Stripe from "https://esm.sh/stripe@14?target=deno";
21	
22	const corsHeaders = {
23	  "Access-Control-Allow-Origin": "*",
24	  "Access-Control-Allow-Headers":
25	    "authorization, x-client-info, apikey, content-type",
26	};
27	
28	serve(async (req: Request) => {
29	  if (req.method === "OPTIONS") {
30	    return new Response("ok", { headers: corsHeaders });
31	  }
32	
33	  try {
34	    // ── 1. Auth ────────────────────────────────────────────────────
35	    const authHeader = req.headers.get("Authorization");
36	    if (!authHeader) {
37	      return new Response(
38	        JSON.stringify({ error: "Missing Authorization header" }),
39	        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
40	      );
41	    }
42	
43	    const supabaseUser = createClient(
44	      Deno.env.get("SUPABASE_URL") ?? "",
45	      Deno.env.get("SUPABASE_ANON_KEY") ?? "",
46	      { global: { headers: { Authorization: authHeader } } }
47	    );
48	
49	    const {
50	      data: { user },
51	      error: userError,
52	    } = await supabaseUser.auth.getUser();
53	
54	    if (userError || !user) {
55	      return new Response(
56	        JSON.stringify({ error: "Unauthorized" }),
57	        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
58	      );
59	    }
60	
61	    // ── 2. Get profile and stripe_customer_id ──────────────────────
62	    const supabaseAdmin = createClient(
63	      Deno.env.get("SUPABASE_URL") ?? "",
64	      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
65	    );
66	
67	    const { data: profile, error: profileError } = await supabaseAdmin
68	      .from("profiles")
69	      .select("stripe_customer_id")
70	      .eq("id", user.id)
71	      .single();
72	
73	    if (profileError || !profile?.stripe_customer_id) {
74	      return new Response(
75	        JSON.stringify({
76	          error: "No active subscription found. Please upgrade to a paid plan first.",
77	        }),
78	        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
79	      );
80	    }
81	
82	    // ── 3. Create Billing Portal session ──────────────────────────
83	    const stripe = new Stripe(Deno.env.get("STRIPE_SECRET_KEY") ?? "", {
84	      apiVersion: "2024-06-20",
85	      httpClient: Stripe.createFetchHttpClient(),
86	    });
87	
88	    const origin = Deno.env.get("SITE_URL") ?? "http://localhost:5173";
89	
90	    const portalSession = await stripe.billingPortal.sessions.create({
91	      customer: profile.stripe_customer_id,
92	      return_url: `${origin}/settings?tab=billing`,
93	    });
94	
95	    return new Response(
96	      JSON.stringify({ url: portalSession.url }),
97	      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
98	    );
99	  } catch (error: unknown) {
100	    const message = error instanceof Error ? error.message : "Internal server error";
101	    console.error("stripe-portal error:", error);
102	    return new Response(
103	      JSON.stringify({ error: message }),
104	      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
105	    );
106	  }
107	});
