63	interface PageSpeedMetrics {
64	  lcp: number;
65	  cls: number;
66	  tbt: number;
67	  fcp: number;
68	  ttfb: number;
69	  speed_index: number;
70	}
71	
72	interface PageSpeedResponse {
73	  score: number;
74	  findings: Finding[];
75	  metrics: PageSpeedMetrics;
76	}
77	
78	// ── Handler ───────────────────────────────────────────────────
79	
80	serve(async (req: Request) => {
81	  if (req.method === "OPTIONS") {
82	    return new Response("ok", { headers: corsHeaders });
83	  }
84	
85	  if (req.method !== "POST") {
86	    return corsResponse({ error: "Method not allowed" }, 405);
87	  }
88	
89	  // Parse request body
90	  let url: string;
91	  let strategy: "mobile" | "desktop" = "mobile";
92	  try {
93	    const body = await req.json();
94	    url = body.url;
95	    if (body.strategy === "desktop") strategy = "desktop";
96	    if (!url || typeof url !== "string") {
97	      return corsResponse({ error: "url is required" }, 400);
98	    }
99	    new URL(url); // validate format
100	  } catch (_e) {
101	    return corsResponse({ error: "Invalid request body or URL" }, 400);
102	  }
103	
104	  const apiKey = Deno.env.get("PAGESPEED_API_KEY");
105	  if (!apiKey) {
106	    console.warn("PAGESPEED_API_KEY not configured — returning fallback");
107	    return corsResponse(buildFallbackResponse());
108	  }
109	
110	  // ── Call Google PageSpeed Insights API ─────────────────────
111	  const psUrl = new URL(
112	    "https://www.googleapis.com/pagespeedonline/v5/runPagespeed",
113	  );
114	  psUrl.searchParams.set("url", url);
115	  psUrl.searchParams.set("key", apiKey);
116	  psUrl.searchParams.set("strategy", strategy);
117	  psUrl.searchParams.set("category", "performance");
118	
119	  let psData: Record<string, unknown>;
120	  try {
121	    const res = await fetch(psUrl.toString(), {
122	      signal: AbortSignal.timeout(35_000),
123	    });
124	    if (!res.ok) {
125	      const text = await res.text();
126	      console.error(`PageSpeed API error ${res.status}:`, text.slice(0, 300));
127	      return corsResponse(buildFallbackResponse(), 200); // soft-fail, don't crash scan
128	    }
129	    psData = await res.json();
130	  } catch (e) {
131	    console.error("PageSpeed fetch failed:", e);
132	    return corsResponse(buildFallbackResponse(), 200);
133	  }
134	
135	  const result = parsePageSpeedResponse(psData, strategy);
136	  return corsResponse(result);
137	});
