383	// ── Helper to build a Finding ─────────────────────────────────
384	
385	function makeFinding(
386	  id: string,
387	  title: string,
388	  severity: Severity,
389	  current_state: string,
390	  recommendation: string,
391	  ai_suggestion: string,
392	  is_premium: boolean,
393	  effort: Effort,
394	  estimated_lift: string,
395	  category: string,
396	): Finding {
397	  return {
